import{_ as s,a0 as a,w as l,s as p,ao as c,I as e,x as t,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 有问必答： 如何在Linux中加入cron任务 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答： 如何在Linux中加入cron任务 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答： 如何在Linux中加入cron任务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答： 如何在Linux中加入cron任务 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux","title":"Linux 有问必答： 如何在Linux中加入cron任务","tag":"201502","desc":""},"relativePath":"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux.md","filePath":"[post].md"}'),d={name:"201502/20150122 Linux FAQs with Answers--How to add a cron job on Linux.md"};function u(m,n,x,g,h,L){const o=a("Link");return l(),p("div",null,[n[11]||(n[11]=c(`<h1 id="linux-有问必答-如何在linux中加入cron任务" tabindex="-1">Linux 有问必答： 如何在Linux中加入cron任务 <a class="header-anchor" href="#linux-有问必答-如何在linux中加入cron任务" aria-label="Permalink to “Linux 有问必答： 如何在Linux中加入cron任务”">​</a></h1><blockquote><p><strong>提问</strong>： 我想在我的Linux中安排一个计划任务，该任务在固定时间周期性地运行。我该如何在Linux中添加一个cron任务？</p></blockquote><p>cron是Linux中默认的计划任务。使用cron，你可以安排一个计划（比如：命令或者shell脚本）周期性地运行或者在指定的分钟、小时、天、周、月等特定时间运行。cron在你安排不同的常规维护任务时是很有用的，比如周期性地备份、日志循环、检查文件系统、监测磁盘空间等等。</p><h3 id="从命令行中添加cron任务" tabindex="-1">从命令行中添加cron任务 <a class="header-anchor" href="#从命令行中添加cron任务" aria-label="Permalink to “从命令行中添加cron任务”">​</a></h3><p>要添加cron任务，你可以使用称为crontab的命令行工具。</p><p>输入下面的命令会创建一个以当前用户运行的新cron任务。</p><pre><code>$ crontab -e
</code></pre><p>如果你想要以其他用户运行cron任务，输入下面的命令。</p><pre><code>$ sudo crontab -u &lt;username&gt; -e
</code></pre><p>你将会看见一个文本编辑窗口，这里你可以添加或者编辑cron任务。默认使用nono编辑器。</p><p><img src="https://farm9.staticflickr.com/8586/16200331362_1385807ac0_b.jpg" alt=""></p><p>每个cron任务的格式如下。</p><pre><code>&lt;分钟&gt; &lt;小时&gt; &lt;日&gt; &lt;月&gt; &lt;星期&gt; &lt;命令&gt;
</code></pre><p>前5个元素定义了任务的计划，最后一个元素是命令或者脚本的完整路径。</p><p><img src="https://farm8.staticflickr.com/7472/16199272841_dffe0b2873_b.jpg" alt=""></p><p>下面是一些cron任务示例。</p><ul><li><strong>* * * * * /home/dan/bin/script.sh</strong>: 每分钟运行。</li><li><strong>0 * * * * /home/dan/bin/script.sh</strong>: 每小时运行。</li><li><strong>0 0 * * * /home/dan/bin/script.sh</strong>: 每天零点运行。</li><li><strong>0 9,18 * * * /home/dan/bin/script.sh</strong>: 在每天的9AM和6PM运行。</li><li><strong>0 9-18 * * * /home/dan/bin/script.sh</strong>: 在9AM到6PM的每个小时运行。</li><li><strong>0 9-18 * * 1-5 /home/dan/bin/script.sh</strong>: 周一到周五的9AM到6PM每小时运行。</li><li><strong>*/10 * * * * /home/dan/bin/script.sh</strong>: 每10分钟运行。</li></ul><p>一旦完成上面的设置步骤后，按下Ctrl+X来保存并退出编辑器。此时，新增的计划任务应该已经激活了。</p><p>要查看存在的计划任务，使用下面的命令：</p><pre><code>$ crontab -l
</code></pre><h3 id="从gui添加计划任务" tabindex="-1">从GUI添加计划任务 <a class="header-anchor" href="#从gui添加计划任务" aria-label="Permalink to “从GUI添加计划任务”">​</a></h3><p>如果你在Linux桌面环境中，你可以使用crontab的更加友好的GUI前端来添加或者添加一个cron任务。</p><p>在Gnome桌面中，有一个Gnome Schedule（gnome-schedule包）。</p><p><img src="https://farm8.staticflickr.com/7484/16015054699_d96f0e9b6a_c.jpg" alt=""></p><p>在KDE桌面中，有一个Task Scheduler（kcron包）。</p><p><img src="https://farm8.staticflickr.com/7473/16175298266_825376c901_c.jpg" alt=""></p><hr>`,27)),e("p",null,[n[1]||(n[1]=t("via: ",-1)),r(o,{href:"http://ask.xmodulo.com/add-cron-job-linux.html"},{default:i(()=>[...n[0]||(n[0]=[t("http://ask.xmodulo.com/add-cron-job-linux.html",-1)])]),_:1})]),e("p",null,[n[4]||(n[4]=t("译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:i(()=>[...n[2]||(n[2]=[t("geekpi",-1)])]),_:1}),n[5]||(n[5]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:i(()=>[...n[3]||(n[3]=[t("wxy",-1)])]),_:1})]),e("p",null,[n[8]||(n[8]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:i(()=>[...n[7]||(n[7]=[t("Linux中国",-1)])]),_:1}),n[10]||(n[10]=t(" 荣誉推出",-1))])])}const T=s(d,[["render",u]]);export{_ as __pageData,T as default};
